const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={queued:'排隊中',processing:'處理中',simulated:'模擬完成',accepted:'API 已接受',failed:'處理失敗',handoff:'人工接管',window_closed:'窗口已關閉',needs_review:'發送待核對'};
let demo=[],human={},api='',token='',selected='',currentTab='lab',busy=false,polling=false,settings=null;
try{const saved=JSON.parse(localStorage.getItem('sm-flow-demo')||'{}');demo=saved.jobs||[];human=saved.human||{};api=sessionStorage.getItem('sm-api')||'';token=sessionStorage.getItem('sm-token')||'';}catch{}
let jobs=demo;
// Browser simulation resumes only while this page is open; it is not a server worker.
demo.forEach(j=>{if(j.status==='processing')j.status='queued'});
const clock=t=>new Date(t*1000).toLocaleTimeString('zh-HK',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});
const fulltime=t=>new Date(t*1000).toLocaleString('zh-HK',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3800)}
function persist(){localStorage.setItem('sm-flow-demo',JSON.stringify({jobs:demo.slice(0,100),human}))}
function log(j,kind,detail){j.events.push({at:Date.now()/1000,kind,detail});j.updated=Date.now()/1000}
function masked(text){return text.replace(/(?<!\d)(?:\+?852[ -]?)?[456789]\d{3}[ -]?\d{4}(?!\d)/g,'[電話]').replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g,'[電郵]').replace(/(?:我叫|姓名[：:])[^，,。\s]{1,16}/g,'姓名：[姓名]').replace(/[A-Za-zＡ-Ｚ一二三四五六七八九十]+座\s*\d+\s*(?:樓)?\s*\d*\s*室/g,'[單位]')}
async function request(path,body,base=api,key=token){const res=await fetch(base.replace(/\/$/,'')+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+key,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(12000)});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error(typeof data.detail==='string'?data.detail:'API 回應失敗：'+res.status);return data}
async function load(){if(!api){jobs=demo;render();return}if(polling)return;polling=true;try{const data=await request('/api/jobs');jobs=data.jobs;render()}catch(e){$('noticeTitle').textContent='後端暫時未能連接';$('noticeText').textContent='畫面可能係上次載入紀錄。請檢查服務、Token 及 CORS 設定。';}finally{polling=false}}
function switchTab(name){currentTab=name;for(const tab of ['lab','jobs','settings'])$('tab-'+tab).hidden=tab!==name;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));const titles={lab:['流程測試','每一次對話，都有跡可循。','由一則訊息開始，驗證你嘅 AI 客服流程。'],jobs:['任務紀錄','每個任務，都有清楚嘅去向。','查看處理狀態、回覆與操作紀錄。'],settings:['連接設定','將測試，接上真正嘅執行層。','連接 Python FastAPI，啟用持久任務與背景 Worker。']};$('crumb').textContent=titles[name][0];$('pageTitle').textContent=titles[name][1];$('pageSubtitle').textContent=titles[name][2]}
document.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>switchTab(x.dataset.tab));document.querySelectorAll('[data-goto]').forEach(x=>x.onclick=()=>switchTab(x.dataset.goto));$('connectShortcut').onclick=()=>switchTab('settings');
function row(j){return `<tr><td>${esc(j.message.slice(0,38))}${j.message.length>38?'…':''}<small>${esc(j.id)}</small></td><td>${esc(j.contact_id)}</td><td><span class="status ${esc(j.status)}">${esc(labels[j.status]||j.status)}</span></td><td>${fulltime(j.created)}</td><td><button class="textbtn viewjob" data-id="${esc(j.id)}">查看 ↗</button></td></tr>`}
function bindRows(){document.querySelectorAll('.viewjob').forEach(x=>x.onclick=()=>{selected=x.dataset.id;switchTab('lab');render();if(innerWidth<650)$('resultArea').scrollIntoView({behavior:'smooth',block:'center'})})}
function render(){
 $('modeBadge').textContent=api?'● 已連接 Python 後端':'● 瀏覽器模擬模式';
 if(api){$('noticeTitle').textContent='已連接後端；測試按鈕仍然唔會發送 WhatsApp。';$('noticeText').textContent=`SQLite 保存任務 · ${settings?.worker||'Worker'} · AI：${settings?.ai_provider||'待確認'} · 固定測試空位。正式發送開關只影響 webhook 任務。`;}
 else{$('noticeTitle').textContent='而家係安全模擬，唔會發送 WhatsApp。';$('noticeText').textContent='頁面用本機規則模擬回答，紀錄只存於此瀏覽器。連接 Python 後端後，先可測試 SQLite、Worker 與外部 API。';}
 $('navCount').textContent=jobs.length;$('statTotal').textContent=jobs.length;
 const done=jobs.filter(j=>['simulated','accepted'].includes(j.status));$('statDone').textContent=done.length;$('statIssues').textContent=jobs.filter(j=>['failed','needs_review','handoff','window_closed'].includes(j.status)).length;
 $('statTime').textContent=done.length?(done.reduce((n,j)=>n+j.updated-j.created,0)/done.length).toFixed(1)+'s':'—';
 $('recentRows').innerHTML=jobs.slice(0,5).map(row).join('')||'<tr><td colspan="5" class="emptyrow">未有任務。發送第一則測試訊息開始。</td></tr>';
 const filtered=jobs.filter(j=>$('statusFilter').value==='all'||j.status===$('statusFilter').value);
 $('allRows').innerHTML=filtered.map(row).join('')||'<tr><td colspan="5" class="emptyrow">未有符合條件嘅任務。</td></tr>';bindRows();
 const j=jobs.find(x=>x.id===selected);const stage=j?.stage||0;
 $('pipeline').innerHTML=['接收訊息','背景排隊','AI 處理','準備回覆'].map((s,i)=>`<div class="step ${stage>i?'complete':stage===i&&j?'current':''}"><i>${stage>i?'✓':i+1}</i>${s}</div>`).join('');
 if(j){$('resultArea').innerHTML=`<div class="resulttop"><span>${esc(j.id.slice(0,28))}</span><span class="status ${esc(j.status)}">${esc(labels[j.status]||j.status)}</span></div>${j.reply?`<div class="replycard"><div class="replytitle"><b>✦ ${j.provider==='deepseek'?'DeepSeek 回答':'規則模擬回答'}</b><span>${j.mode==='test'?'測試入口':'Webhook'}</span></div><p>${esc(j.reply)}</p><small>${j.status==='accepted'?'API 已接受，尚未驗證 WhatsApp 送達':'未宣告 WhatsApp 送達；請以任務狀態為準。'}</small></div>`:''}${j.error?`<div class="errorbox">${esc(j.error)}</div>`:''}<div class="eventlist">${(j.events||[]).map(e=>`<div class="event"><time>${clock(e.at)}</time><span>${esc(e.detail)}</span></div>`).join('')}</div><div class="resultactions">${j.status==='failed'?'<button class="button secondary" id="retryBtn">↻ 重試任務</button>':''}${j.mode==='test'?'<button class="textbtn" id="duplicateBtn">重送同一事件（測試去重）</button>':''}</div>`;
 if($('retryBtn'))$('retryBtn').onclick=()=>retry(j);if($('duplicateBtn'))$('duplicateBtn').onclick=()=>duplicate(j);
 }
 const contact=$('contact').value;const held=api?jobs.some(j=>j.contact_id===contact&&j.human):!!human[contact];$('contactState').textContent=held?'人工已接管 · AI 暫停':'AI 可處理';$('takeoverBtn').textContent=held?'恢復 AI':'人工接管';$('contactDot').style.background=held?'#b99a53':'#3d9c73';
}
$('statusFilter').onchange=render;$('contact').onchange=render;$('message').oninput=()=>$('charCount').textContent=$('message').value.length+' / 4000';document.querySelectorAll('[data-prompt]').forEach(x=>x.onclick=()=>{$('message').value=x.dataset.prompt;$('message').oninput();$('message').focus()});
async function demoWork(){if(busy)return;busy=true;try{while(true){const j=[...demo].reverse().find(x=>x.status==='queued');if(!j)break;if(human[j.contact_id]){j.status='handoff';log(j,'handoff','人工已接管，不處理任務');persist();render();continue}j.status='processing';j.stage=1;j.attempts++;log(j,'claimed','瀏覽器開始模擬處理（非 Python Worker）');persist();render();await new Promise(r=>setTimeout(r,600));if(j.status!=='processing')continue;j.stage=2;log(j,'masked','已套用基本個資遮蓋規則；不保證完整匿名');render();await new Promise(r=>setTimeout(r,600));if(j.status!=='processing')continue;
 if(j.fail_once&&j.attempts===1){j.status='failed';j.error='測試注入故障；尚未發送，可重試。';log(j,'failed',j.error);persist();render();continue}
 j.intent=/驗樓|空位|星期|時段|下午/.test(j.message)?'inspection':'other';j.reply=j.intent==='inspection'?'你好呀！測試資料顯示星期六上午10點、下午2點可選。你想揀邊個時段？\n【只供測試，未查真實日曆，未建立預約】':'你好！呢度係叻媽驗樓流程測試。呢個問題需要由客服跟進。\n【規則模擬，未呼叫 DeepSeek】';j.stage=3;log(j,'answered','規則模擬回答完成；未呼叫 DeepSeek');render();await new Promise(r=>setTimeout(r,500));if(j.status!=='processing')continue;
 if(human[j.contact_id]){j.status='handoff';log(j,'handoff','發送前檢查：人工接管，停止')}else{j.stage=4;j.status='simulated';log(j,'simulated','回覆已保存，沒有發送 WhatsApp')}
 persist();render();}}
 finally{busy=false}}
async function send(){const text=$('message').value.trim();if(!text){toast('先輸入一則測試訊息。');$('message').focus();return}$('sendBtn').disabled=true;try{const body={message:text,contact_id:$('contact').value,message_id:'test-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),fail_once:$('failOnce').checked};if(api){const r=await request('/api/test/messages',body);selected=r.id;await load();toast('已交畀後端，等待 Worker 處理。')}else{const now=Date.now()/1000;const j={id:body.message_id,contact_id:body.contact_id,message:masked(text),created:now,updated:now,status:human[body.contact_id]?'handoff':'queued',stage:0,attempts:0,reply:null,error:null,fail_once:body.fail_once,mode:'test',provider:'mock',events:[]};log(j,'received','模擬事件已保存於此瀏覽器');demo.unshift(j);selected=j.id;persist();render();demoWork()}$('message').value='';$('message').oninput()}catch(e){toast('提交失敗：'+e.message)}finally{$('sendBtn').disabled=false}}
$('sendBtn').onclick=send;
async function retry(j){try{if(api){await request('/api/jobs/'+encodeURIComponent(j.id)+'/retry',{});await load()}else{if(j.status!=='failed')return;j.status='queued';j.stage=0;j.error=null;log(j,'retry','人工重試尚未發送的任務');persist();render();demoWork()}toast('已重新排隊。')}catch(e){toast(e.message)}}
async function duplicate(j){try{if(api){const r=await request('/api/test/messages',{message:j.message,contact_id:j.contact_id,message_id:j.id,fail_once:!!j.fail_once});toast(r.duplicate?'重複事件已攔截，冇建立新任務。':'已提交事件');await load()}else{toast('重複 Message ID 已攔截，任務數量不變。')}}catch(e){toast(e.message)}}
$('takeoverBtn').onclick=async()=>{const id=$('contact').value;const held=api?jobs.some(j=>j.contact_id===id&&j.human):!!human[id];try{if(api){await request('/api/contacts/'+encodeURIComponent(id)+'/takeover',{human:!held});await load()}else{human[id]=!held;if(human[id])demo.filter(j=>j.contact_id===id&&['queued','processing'].includes(j.status)).forEach(j=>{j.status='handoff';log(j,'handoff','人工已接管，停止自動處理')});persist();render()}toast(held?'已恢復 AI；舊接管任務不會自動重送。':'已人工接管此測試客人。')}catch(e){toast(e.message)}};
$('apiUrl').value=api;$('apiToken').value=token;
function renderConfig(){if(!settings)return;$('capabilities').innerHTML=Object.entries({'資料庫':settings.storage,'背景 Worker':settings.worker,'AI':settings.ai_provider,'日曆':settings.calendar,'Webhook 真實發送':settings.live_send?'已啟用（僅限白名單）':'關閉','測試電話白名單':settings.allowlist_count+' 個'}).map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}
$('connectBtn').onclick=async()=>{let url=$('apiUrl').value.trim().replace(/\/$/,'');const key=$('apiToken').value.trim();try{const parsed=new URL(url);if(parsed.protocol!=='https:'&&!(parsed.protocol==='http:'&&['localhost','127.0.0.1'].includes(parsed.hostname)))throw Error('請使用 HTTPS 後端網址。');if(parsed.username||parsed.password||parsed.search||parsed.hash)throw Error('網址不可包含密碼、查詢參數或片段。');if(!key)throw Error('請填入 ADMIN_TOKEN。');$('connectBtn').disabled=true;const result=await request('/api/config',undefined,url,key);api=url;token=key;settings=result;sessionStorage.setItem('sm-api',api);sessionStorage.setItem('sm-token',token);$('connectionResult').textContent='✓ 後端連接成功。測試任務只保存回覆，不發 WhatsApp。';renderConfig();await load();toast('已連接 Python 後端。')}catch(e){$('connectionResult').textContent='連接失敗：'+e.message+'。請檢查服務、HTTPS 及 CORS。'}finally{$('connectBtn').disabled=false}};
$('disconnectBtn').onclick=()=>{api='';token='';settings=null;sessionStorage.removeItem('sm-api');sessionStorage.removeItem('sm-token');$('apiToken').value='';jobs=demo;selected='';$('connectionResult').textContent='已切換至瀏覽器模擬模式。';render();toast('已離開後端模式。')};
$('clearBtn').onclick=()=>{if(!confirm('清除此瀏覽器的模擬紀錄？不影響後端資料。'))return;demo=[];human={};persist();if(!api){jobs=demo;selected='';$('resultArea').innerHTML='<div class="empty"><div class="empty-icon">✦</div><h3>紀錄已清除。</h3><p>可以開始新一輪測試。</p></div>'}render();toast('瀏覽器模擬紀錄已清除。')};
$('exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({exported_at:new Date().toISOString(),mode:api?'backend':'browser-simulation',jobs},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='supermama-flow-test-log.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已匯出目前載入的測試紀錄。')};
$('helpBtn').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('helpDialog').onclick=e=>{if(e.target===$('helpDialog'))$('helpDialog').close()};
render();if(api){request('/api/config').then(r=>{settings=r;renderConfig();load()}).catch(()=>load())}else demoWork();setInterval(()=>{if(api)load()},2000);
